test.source:

class Account {
  Int balance

  Account(Int start) {
    this.balance = start
  }

  Int deposit(Int amount) {
    this.balance = this.balance + amount
    return this.balance
  }

  static run() {
    var a = Account(100)
    print("bal=" + a.deposit(50))
    try {
      throw "overdraft"
    } catch String e {
      print("caught=" + e)
    }
  }
}
